package com.fintrack.khmtomnenh.rfq.service; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.product.entity.Product; import com.fintrack.khmtomnenh.product.repository.ProductRepository; import com.fintrack.khmtomnenh.rfq.dto.RfqDto; import com.fintrack.khmtomnenh.rfq.entity.Rfq; import com.fintrack.khmtomnenh.rfq.repository.RfqRepository; import com.fintrack.khmtomnenh.rfqitem.entity.RfqItem; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class RfqService {private final RfqRepository repo;private final ProductRepository products;public List<Rfq> mine(Auth a){return repo.findByBuyerIdOrderByCreatedAtDesc(a.getId());}public List<Rfq> open(){return repo.findByStatusOrderByCreatedAtDesc("OPEN");}public Rfq get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("RFQ not found"));}@Transactional public Rfq create(RfqDto d,Auth a){Rfq r=Rfq.builder().buyer(a).title(d.title().trim()).description(d.description()).expiresAt(d.expiresAt()).build();for(RfqDto.Item x:d.items()){Product p=products.findById(x.productId()).orElseThrow(()->new IllegalArgumentException("Product not found: "+x.productId()));if(!Boolean.TRUE.equals(p.getActive()))throw new IllegalArgumentException("Product is inactive");r.getItems().add(RfqItem.builder().rfq(r).product(p).quantity(x.quantity()).targetPrice(x.targetPrice()).build());}return repo.save(r);}public void assertBuyer(Rfq r,Auth a){if(!r.getBuyer().getId().equals(a.getId()))throw new AccessDeniedException("Not RFQ owner");}}
